# Peptide Collapse attribution and licensing are recorded in NOTICE.
# Generated by tools/export_notebook_tables.py.
from __future__ import annotations

import pandas as pd

import re

_SAMPLE_DOTTED_SUFFIX = re.compile(
    r"(?:(?:\.(?:PG|GG|EG|FG|PEP|PR|Precursor|Protein|Peptide))?\."
    r"(?:(?:Avg|Average)?Log[._\s-]*2(?:Normal(?:i[sz]ed|isation|ization))?"
    r"(?:Quantity|Intensity|Abundance)|Normal(?:i[sz]ed|isation|ization)"
    r"(?:Quantity|Intensity|Abundance)?|Max[._\s-]*LFQ(?:Quantity|Intensity|Abundance)?|"
    r"TotalQuantity|Quantity|Intensity|Abundance))$",
    re.IGNORECASE,
)

_SAMPLE_TEXT_SUFFIX = re.compile(
    r"[\s._-]+(?:(?:Max[\s._-]*LFQ[\s._-]+)?"
    r"(?:Unique[\s._-]+|Total[\s._-]+|Razor[\s._-]+)?Intensity|"
    r"(?:Unique[\s._-]+|Total[\s._-]+|Razor[\s._-]+)?Spectral[\s._-]+Count|"
    r"PSMs?|Percent[\s._-]+PSMs?|LFQ[\s._-]+Intensity|iBAQ|"
    r"MS\s*/\s*MS[\s._-]+Count|MS[12][\s._-]+(?:Intensity|Count)|"
    r"Razor\s*\+\s*Unique[\s._-]+Peptides|Unique[\s._-]+Peptides|Peptides|"
    r"Sequence[\s._-]+Coverage(?:[\s._-]*\[%\])?|"
    r"Log[._\s-]*2[\s._-]*(?:Quantity|Intensity|Abundance|Ratio)|"
    r"(?:Quantity|Abundance|Ratio))$",
    re.IGNORECASE,
)

_SAMPLE_ACQUISITION_SUFFIX = re.compile(r"\.(?:d|htrms|raw|wiff2?|mzml|mzxml)$", re.IGNORECASE)

_SAMPLE_NUMBER = re.compile(r"\d+")

def strip_sample_measurement_suffix(value):
    sample = re.split(r"[\\/]", str(value).strip())[-1]
    previous = None
    while sample != previous:
        previous = sample
        sample = _SAMPLE_DOTTED_SUFFIX.sub("", sample).rstrip()
        sample = _SAMPLE_TEXT_SUFFIX.sub("", sample).rstrip()
    return _SAMPLE_ACQUISITION_SUFFIX.sub("", sample).rstrip()

def extract_sample_id(value):
    original = str(value).strip()
    numbers = _SAMPLE_NUMBER.findall(strip_sample_measurement_suffix(original))
    return numbers[-1] if numbers else original

def _grouped_meta_order(meta: pd.DataFrame) -> pd.DataFrame:
    if meta.empty:
        return meta.copy()

    ordered = meta.copy()
    ordered["condition"] = ordered["condition"].astype(str)
    condition_order = ordered["condition"].dropna().drop_duplicates().tolist()
    if not condition_order:
        return ordered.reset_index(drop=True)

    ordered["__condition_order"] = pd.Categorical(
        ordered["condition"],
        categories=condition_order,
        ordered=True,
    )
    ordered = ordered.sort_values("__condition_order", kind="stable")
    return ordered.drop(columns="__condition_order").reset_index(drop=True)

def prepare_coverage_df(data: pd.DataFrame, meta: pd.DataFrame, name: bool = False) -> pd.DataFrame:
    data = data.copy()
    meta = _grouped_meta_order(meta.copy())
    meta["sample"] = meta["sample"].astype(str)
    meta["new_sample"] = meta.groupby("condition").cumcount() + 1
    meta["new_sample"] = meta.apply(lambda row: f"{row['condition']}_{row['new_sample']}", axis=1)

    rename_dict = dict(zip(meta["sample"], meta["new_sample"]))
    data_filtered = data.rename(columns=rename_dict)
    annotated_columns = [c for c in meta["new_sample"].tolist() if c in data_filtered.columns]
    if not annotated_columns:
        return pd.DataFrame(columns=["Sample", "Number"])

    data_filtered = data_filtered[annotated_columns].notna().astype(int)
    data_long = data_filtered.reset_index(drop=True).melt(var_name="Sample", value_name="Number")

    if name:
        data_annotated = data_long.merge(
            meta[["sample", "new_sample"]],
            left_on="Sample",
            right_on="new_sample",
            how="left",
        )
        summary = (
            data_annotated.groupby(["Sample", "sample"], as_index=False)["Number"]
            .sum()
            .rename(columns={"sample": "Original_Name"})
        )
        summary = summary[["Sample", "Number", "Original_Name"]]
    else:
        summary = data_long.groupby("Sample", as_index=False)["Number"].sum()

    summary["Sample"] = pd.Categorical(summary["Sample"], categories=annotated_columns, ordered=True)
    summary = summary.sort_values(["Sample"])

    # The union of the per-sample counts above, not the row count of the matrix.
    # A feature can be identified -- real sequence, localization, protein -- with
    # no quantity surviving in any run, and those rows are in the matrix but in
    # none of the bars. Counting them here made the total larger than the union
    # of the rows beneath it, and disagree with the missing-value plot, which
    # already excludes them.
    quantified_anywhere = data_filtered.sum(axis=1) > 0
    total_value = int(quantified_anywhere.sum())

    all_samples_row: dict[str, object] = {"Sample": "All samples", "Number": total_value}
    if name:
        all_samples_row["Original_Name"] = ""
    extra_rows = [all_samples_row]

    # Never silently dropped: an identified-but-unquantified feature is a real
    # finding (two of the HEK293 ones are Class I), so the count is stated rather
    # than folded into the total or left out of the table altogether.
    identified_only = int(len(quantified_anywhere) - total_value)
    if identified_only:
        unquantified_row: dict[str, object] = {
            "Sample": "Identified, not quantified",
            "Number": identified_only,
        }
        if name:
            unquantified_row["Original_Name"] = ""
        extra_rows.append(unquantified_row)

    summary = pd.concat([summary, pd.DataFrame(extra_rows)], ignore_index=True)
    return summary

def prepare_coverage_summary_df(data: pd.DataFrame, meta: pd.DataFrame) -> pd.DataFrame:
    data = data.copy()
    meta = _grouped_meta_order(meta.copy())
    meta["sample"] = meta["sample"].astype(str)
    meta["condition"] = meta["condition"].astype(str)
    condition_order = meta["condition"].dropna().unique().tolist()
    meta["id"] = meta["sample"].apply(extract_sample_id)
    meta["new_sample"] = meta.groupby("condition").cumcount() + 1
    meta["new_sample"] = meta.apply(
        lambda row: f"{row['condition']}_{row['new_sample']}\n({row['id']})",
        axis=1,
    )

    rename_dict = dict(zip(meta["sample"], meta["new_sample"]))
    data_filtered = data.rename(columns=rename_dict)
    annotated_cols = [c for c in meta["new_sample"].tolist() if c in data_filtered.columns]
    if not annotated_cols:
        return pd.DataFrame(columns=["condition", "mean", "min", "max", "sd"])

    data_binary = data_filtered[annotated_cols].notna().astype(int)
    melted = data_binary.melt(var_name="Sample", value_name="Value")
    data_annotated = melted.merge(meta[["new_sample", "condition"]], left_on="Sample", right_on="new_sample")

    sample_summary = (
        data_annotated.groupby("Sample", sort=False)
        .agg(Value=("Value", "sum"), condition=("condition", "first"))
        .reset_index()
    )
    condition_summary = (
        sample_summary.groupby("condition", sort=False)
        .agg(mean=("Value", "mean"), min=("Value", "min"), max=("Value", "max"), sd=("Value", "std"))
        .reset_index()
    )

    numeric_cols = ["mean", "min", "max", "sd"]
    condition_summary[numeric_cols] = condition_summary[numeric_cols].round(2)
    if condition_order:
        condition_summary["condition"] = pd.Categorical(
            condition_summary["condition"],
            categories=condition_order,
            ordered=True,
        )
        condition_summary = condition_summary.sort_values("condition").reset_index(drop=True)
        condition_summary["condition"] = condition_summary["condition"].astype(str)
    return condition_summary

def qc_coverage_table(data, metadata, summary: bool = False) -> pd.DataFrame:
    frame = data
    meta = metadata.copy()
    if summary:
        return prepare_coverage_summary_df(frame, meta)
    return prepare_coverage_df(frame, meta)

import numpy as np

def _boxplot_summary(values):
    from matplotlib.cbook import boxplot_stats

    stats = boxplot_stats(values, whis=1.5)[0]
    return {
        name: round(float(stats[key]), 2)
        for name, key in (
            ("mean", "mean"), ("median", "med"), ("Q1", "q1"), ("Q3", "q3"),
            ("lower_whisker", "whislo"), ("upper_whisker", "whishi"),
        )
    }

def prepare_boxplot_df(data: pd.DataFrame, meta: pd.DataFrame) -> pd.DataFrame:
    conditions_order = meta["condition"].unique()
    summary_list: list[dict[str, object]] = []
    for condition in conditions_order:
        columns = meta.loc[meta["condition"] == condition, "sample"].tolist()
        values = data[columns].mean(axis=1, skipna=True).values
        values = values[np.isfinite(values)]
        if len(values) == 0:
            continue

        summary = _boxplot_summary(values)

        summary_list.append(
            {
                "Condition": str(condition),
                **summary,
            }
        )

    summary_df = pd.DataFrame(summary_list)
    if summary_df.empty:
        return summary_df
    return summary_df.reset_index(drop=True)

def prepare_boxplot_single_df(data: pd.DataFrame, meta: pd.DataFrame, name: bool = False) -> pd.DataFrame:
    meta = meta.copy()
    meta["id"] = meta["sample"].apply(extract_sample_id)
    meta["new_sample"] = meta.groupby("condition").cumcount() + 1
    meta["new_sample"] = meta.apply(lambda row: f"{row['condition']}_{row['new_sample']}", axis=1)

    rename_dict = dict(zip(meta["sample"], meta["new_sample"]))
    data_renamed = data.rename(columns=rename_dict)
    samples = [s for s in meta["new_sample"].tolist() if s in data_renamed.columns]

    summary_list: list[dict[str, object]] = []
    for sample in samples:
        values = data_renamed[sample].values
        values = values[np.isfinite(values)]
        if len(values) == 0:
            continue

        summary = _boxplot_summary(values)

        row_dict: dict[str, object] = {
            "Sample": sample,
            **summary,
        }
        if name:
            original_name = meta.loc[meta["new_sample"] == sample, "sample"].values[0]
            row_dict["Original_Name"] = str(original_name)
        summary_list.append(row_dict)

    summary_df = pd.DataFrame(summary_list)
    if summary_df.empty:
        return summary_df
    return summary_df.reset_index(drop=True)

def qc_boxplot_table(data, metadata, mode: str = "Mean") -> pd.DataFrame:
    frame = data
    sample_columns = metadata['sample'].tolist()
    meta = metadata.copy()
    numeric = frame[sample_columns].apply(pd.to_numeric, errors="coerce")
    if str(mode).lower() == "single":
        return prepare_boxplot_single_df(numeric, meta)
    return prepare_boxplot_df(numeric, meta)

def prepare_cov_df(data: pd.DataFrame, meta: pd.DataFrame) -> pd.DataFrame:
    summary_list: list[dict[str, object]] = [
        {"Condition": condition, **_boxplot_summary(cv)} for condition, cv in condition_cvs(data, meta)
    ]

    summary_df = pd.DataFrame(summary_list)
    if summary_df.empty:
        return summary_df
    return summary_df.reset_index(drop=True)

def qc_cv_table(data, metadata) -> pd.DataFrame:
    frame = data
    sample_columns = metadata['sample'].tolist()
    frame = raw_zero_to_nan(frame, sample_columns)
    meta = metadata.copy()
    numeric = frame[sample_columns].apply(pd.to_numeric, errors="coerce")
    return prepare_cov_df(numeric, meta)

def raw_zero_to_nan(data: pd.DataFrame, sample_columns: list[str]) -> pd.DataFrame:
    """Apply the raw-intensity missing-value convention to measurement columns.

    A zero in imported linear intensity data means "not detected".  This
    conversion belongs at the raw-data boundary only: zero is a valid value on
    log2 and other transformed scales (``2 ** 0 == 1``).  Restricting the
    conversion to declared sample columns also protects numeric annotations.
    """
    out = data.copy()
    present = [column for column in sample_columns if column in out.columns]
    if present:
        out[present] = (
            out[present]
            .apply(pd.to_numeric, errors="coerce")
            .replace([np.inf, -np.inf, 0], np.nan)
        )
    return out

def condition_cvs(values: pd.DataFrame, meta: pd.DataFrame) -> list[tuple[str, pd.Series]]:
    """Per-condition coefficient of variation in percent: 100 * SD / mean of each
    row's observed linear values (sample SD, ddof = 1). Conditions with fewer than
    two samples are skipped and non-finite CVs are dropped. The CV plot and its
    table both use this."""
    result: list[tuple[str, pd.Series]] = []
    conditions = meta["condition"].astype(str)
    for condition in conditions.dropna().unique().tolist():
        cols = meta.loc[conditions == condition, "sample"].tolist()
        if len(cols) < 2:
            continue
        subset = values[cols]
        cv = subset.std(axis=1, skipna=True) / subset.mean(axis=1, skipna=True) * 100.0
        cv = cv[np.isfinite(cv)]
        if len(cv):
            result.append((condition, cv))
    return result

def qc_feature_cvs(frame: pd.DataFrame, meta: pd.DataFrame) -> pd.DataFrame:
    samples = meta["sample"].tolist()
    frame = frame.reset_index(drop=True)
    values = raw_zero_to_nan(frame[samples], samples)
    cvs = dict(condition_cvs(values, meta))
    result = frame.drop(columns=samples).copy()
    if result.shape[1] == 0:
        result["Feature row"] = frame.index + 1
    for condition in meta["condition"].astype(str).unique():
        label = f"{condition} CV (%)"
        while label in result.columns:
            label += " (CV)"
        result[label] = cvs.get(condition, np.nan)
    return result

def pearson_table(data, metadata,
    kind: str,
    mode: str = "Single",
    sample1: str = "",
    sample2: str = "",
    condition1: str = "",
    condition2: str = "",
    alias1: str = "",
    alias2: str = "",
    min_present: int = 1,
) -> pd.DataFrame:
    x, y, label1, label2 = _pearson_vectors(
        data, metadata, kind=kind,
        mode=mode,
        sample1=sample1,
        sample2=sample2,
        condition1=condition1,
        condition2=condition2,
        min_present=min_present,
    )

    pairs = pd.DataFrame({"x": x, "y": y}).dropna()
    if pairs.empty:
        raise ValueError("No overlapping non-missing values were found for the selected comparison.")

    label_left = alias1.strip() or label1
    label_right = alias2.strip() or label2
    corr = float(np.corrcoef(pairs["x"], pairs["y"])[0, 1]) if len(pairs) > 1 else float("nan")

    return pd.DataFrame(
        [
            {"Metric": "Left", "Value": label_left},
            {"Metric": "Right", "Value": label_right},
            {"Metric": "Points", "Value": int(len(pairs))},
            {"Metric": "PearsonR", "Value": round(corr, 6) if np.isfinite(corr) else ""},
        ]
    )

def _pearson_vectors(data, metadata,
    kind: str,
    mode: str,
    sample1: str = "",
    sample2: str = "",
    condition1: str = "",
    condition2: str = "",
    min_present: int = 1,
) -> tuple[pd.Series, pd.Series, str, str]:
    frame, meta = data, metadata
    mode_norm = str(mode).strip().lower()

    if mode_norm in {"single", "sample"}:
        if not sample1 or not sample2:
            raise ValueError("Please select two samples.")
        if sample1 == sample2:
            raise ValueError("Please select two different samples.")
        if sample1 not in frame.columns or sample2 not in frame.columns:
            raise ValueError("Selected samples are not available in the current dataset.")

        x = pd.to_numeric(frame[sample1], errors="coerce")
        y = pd.to_numeric(frame[sample2], errors="coerce")
        return x, y, sample1, sample2

    if mode_norm == "condition":
        if not condition1 or not condition2:
            raise ValueError("Please select two conditions.")
        if condition1 == condition2:
            raise ValueError("Please select two different conditions.")

        cols1 = meta.loc[meta["condition"] == condition1, "sample"].astype(str).tolist()
        cols2 = meta.loc[meta["condition"] == condition2, "sample"].astype(str).tolist()
        cols1 = [col for col in cols1 if col in frame.columns]
        cols2 = [col for col in cols2 if col in frame.columns]
        if not cols1 or not cols2:
            raise ValueError("No matching sample columns for one or both selected conditions.")

        x, _ = condition_mean(frame, cols1, min_present=min_present)
        y, _ = condition_mean(frame, cols2, min_present=min_present)
        return x, y, condition1, condition2

    raise ValueError("Mode must be 'Single' or 'Condition'.")

def condition_mean(data, columns, min_present=1):
    """Mean across a condition's replicates, blanked where too few were observed.

    `mean(axis=1)` skips missing values silently, so a condition mean resting on
    one replicate is plotted and correlated at the same weight as a fully
    observed one. Measured on 2000 features with 30% poor coverage, the
    single-replicate means were off by 0.28 log2 on average and 1.21 at worst
    against the same features' fully observed means.

    `min_present` is the smallest number of observations a mean may rest on. The
    default of 1 reports every mean, which is the long-standing behaviour and keeps
    previously generated results reproducible. Pass 2 or more to require that a
    mean rest on enough replicates to carry spread information.

    Returns (means, counts) so the caller can report how many features were
    excluded rather than dropping them silently.
    """
    numeric = data[list(columns)].apply(pd.to_numeric, errors="coerce")
    counts = numeric.notna().sum(axis=1)
    means = numeric.mean(axis=1)
    return means.where(counts >= int(min_present)), counts

def venn_table(data, metadata,
    kind: str,
    mode: str = "Single",
    first: str = "",
    second: str = "",
    third: str = "",
    alias1: str = "",
    alias2: str = "",
    alias3: str = "",
    min_present: int = 1,
) -> pd.DataFrame:
    set1, set2, set3 = _venn_sets(
        data, metadata, kind=kind,
        mode=mode,
        first=first,
        second=second,
        third=third,
        min_present=min_present,
    )
    label1 = alias1.strip() or first
    label2 = alias2.strip() or second
    label3 = alias3.strip() or third

    if set3 is None:
        return pd.DataFrame(
            [
                {"Region": f"{label1} only", "Count": len(set1 - set2)},
                {"Region": f"{label2} only", "Count": len(set2 - set1)},
                {"Region": f"{label1} & {label2}", "Count": len(set1 & set2)},
                {"Region": f"Total {label1}", "Count": len(set1)},
                {"Region": f"Total {label2}", "Count": len(set2)},
            ]
        )

    return pd.DataFrame(
        [
            {"Region": f"{label1} only", "Count": len(set1 - set2 - set3)},
            {"Region": f"{label2} only", "Count": len(set2 - set1 - set3)},
            {"Region": f"{label3} only", "Count": len(set3 - set1 - set2)},
            {"Region": f"{label1} & {label2}", "Count": len((set1 & set2) - set3)},
            {"Region": f"{label1} & {label3}", "Count": len((set1 & set3) - set2)},
            {"Region": f"{label2} & {label3}", "Count": len((set2 & set3) - set1)},
            {"Region": f"{label1} & {label2} & {label3}", "Count": len(set1 & set2 & set3)},
            {"Region": f"Total {label1}", "Count": len(set1)},
            {"Region": f"Total {label2}", "Count": len(set2)},
            {"Region": f"Total {label3}", "Count": len(set3)},
        ]
    )

def _id_column(kind: str, frame: pd.DataFrame) -> str:
    if kind == "protein":
        candidates = ["ProteinNames", "Protein", "Gene"]
    else:
        candidates = ["PTM_Collapse_key", "Phosphoprotein", "Protein_group"]
    for col in candidates:
        if col in frame.columns:
            return col
    raise ValueError(f"No identifier column found for {kind} dataset.")

def _venn_sets(data, metadata,
    kind: str,
    mode: str,
    first: str,
    second: str,
    third: str = "",
    min_present: int = 1,
) -> tuple[set[str], set[str], set[str] | None]:
    frame, meta = data, metadata
    id_col = _id_column(kind, frame)
    mode_norm = str(mode).strip().lower()
    if not first or not second:
        raise ValueError("Please select at least two entries for the Venn diagram.")
    if first == second:
        raise ValueError("Please select two different entries.")
    if third and (third == first or third == second):
        raise ValueError("Please select distinct entries for the third set.")

    if mode_norm in {"single", "sample"}:
        set1 = _feature_set_from_sample(frame, id_col, first)
        set2 = _feature_set_from_sample(frame, id_col, second)
        set3 = _feature_set_from_sample(frame, id_col, third) if third else None
        return set1, set2, set3
    if mode_norm == "condition":
        if not np.isfinite(min_present) or int(min_present) != min_present or min_present < 1:
            raise ValueError("The minimum number of values per condition must be a positive integer.")
        minimum = int(min_present)
        set1 = _feature_set_from_condition(frame, meta, id_col, first, minimum)
        set2 = _feature_set_from_condition(frame, meta, id_col, second, minimum)
        set3 = _feature_set_from_condition(frame, meta, id_col, third, minimum) if third else None
        return set1, set2, set3
    raise ValueError("Mode must be 'Single' or 'Condition'.")

def _feature_set_from_sample(frame: pd.DataFrame, id_col: str, sample: str) -> set[str]:
    if sample not in frame.columns:
        raise ValueError(f"Sample '{sample}' is not available.")
    mask = pd.to_numeric(frame[sample], errors="coerce").notna()
    return set(frame.loc[mask, id_col].dropna().astype(str).tolist())

def _feature_set_from_condition(
    frame: pd.DataFrame, meta: pd.DataFrame, id_col: str, condition: str, min_present: int = 1
) -> set[str]:
    """Features measured in at least `min_present` samples of the condition.

    The default of 1 counts a feature present when any replicate has a value,
    which makes conditions look alike when detection is patchy; a higher
    minimum asks for reproducible detection.
    """
    columns = meta.loc[meta["condition"] == condition, "sample"].astype(str).tolist()
    columns = [col for col in columns if col in frame.columns]
    if not columns:
        raise ValueError(f"Condition '{condition}' has no available sample columns.")
    if min_present > len(columns):
        raise ValueError(
            f"Condition '{condition}' has {len(columns)} samples, fewer than the minimum of {min_present} "
            "values per condition."
        )
    values = frame[columns].apply(pd.to_numeric, errors="coerce")
    mask = values.notna().sum(axis=1) >= min_present
    return set(frame.loc[mask, id_col].dropna().astype(str).tolist())

def phospho_counts_table(data) -> pd.DataFrame:
    # The localization cutoff is the session-wide one, applied in _phospho_context.
    filtered = data

    if filtered.empty:
        return pd.DataFrame({"Term": [], "Count": []})

    protein_col = "Protein_group" if "Protein_group" in filtered.columns else "Phosphoprotein"
    phosphoproteins = int(filtered[protein_col].dropna().astype(str).nunique()) if protein_col in filtered.columns else 0

    if "UPD_seq" in filtered.columns:
        clean_seq = filtered["UPD_seq"].astype(str).str.replace(r"[^\w]", "", regex=True).str.upper()
        phosphopeptides = int(clean_seq.replace("", np.nan).dropna().nunique())
    else:
        phosphopeptides = int(filtered["PTM_Collapse_key"].dropna().astype(str).nunique()) if "PTM_Collapse_key" in filtered.columns else 0

    phosphosites = int(filtered["PTM_Collapse_key"].dropna().astype(str).nunique()) if "PTM_Collapse_key" in filtered.columns else 0

    summary = pd.DataFrame(
        {
            "Term": ["Phosphoproteins", "Phosphopeptides", "Phosphosites"],
            "Count": [phosphoproteins, phosphopeptides, phosphosites],
        }
    ).sort_values("Count", ascending=False)
    return summary.reset_index(drop=True)

def _coverage_counts(data, metadata, is_log2,
    include_id: bool = False,
    conditions: list[str] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    frame, meta = data, metadata

    meta_filtered, selected_conditions = _filter_meta_conditions(meta, conditions)
    meta_filtered["sample_idx"] = meta_filtered.groupby("condition").cumcount() + 1
    if include_id:
        meta_filtered["new_sample"] = meta_filtered.apply(
            lambda row: f"{row['condition']}_{row['sample_idx']}\n({extract_sample_id(row['sample'])})",
            axis=1,
        )
    else:
        meta_filtered["new_sample"] = meta_filtered.apply(
            lambda row: f"{row['condition']}_{row['sample_idx']}",
            axis=1,
        )

    rename_map = dict(zip(meta_filtered["sample"], meta_filtered["new_sample"]))
    labeled_frame = frame.rename(columns=rename_map)
    sample_labels = [rename_map[sample] for sample in meta_filtered["sample"] if sample in frame.columns]
    if not sample_labels:
        raise ValueError("No samples available in phospho dataset for coverage plot.")

    localization = pd.to_numeric(frame.get("PTM_localization", pd.Series(np.nan, index=frame.index)), errors="coerce")
    localization = localization.where(localization.between(0, 1))
    observed = labeled_frame[sample_labels].apply(pd.to_numeric, errors="coerce")
    observed = observed.where(np.isfinite(observed))
    if not is_log2:
        observed = observed.mask(observed == 0)
    class_i = observed.loc[localization >= 0.75]
    not_class_i = observed.loc[localization < 0.75]

    counts = pd.DataFrame(
        {
            "Sample": sample_labels,
            "Class I": class_i.notna().sum().reindex(sample_labels, fill_value=0).astype(int).tolist(),
            "Not Class I": not_class_i.notna().sum().reindex(sample_labels, fill_value=0).astype(int).tolist(),
            "Unclassified": observed.loc[localization.isna()].notna().sum().tolist(),
        }
    )
    sample_to_condition = dict(zip(meta_filtered["new_sample"], meta_filtered["condition"]))
    counts["Condition"] = counts["Sample"].map(sample_to_condition).fillna("sample")
    counts["Total"] = counts[["Class I", "Not Class I", "Unclassified"]].sum(axis=1)

    summary = (
        counts.groupby("Condition", as_index=False)
        .agg(
            classIMean=("Class I", "mean"),
            classISd=("Class I", "std"),
            notClassIMean=("Not Class I", "mean"),
            notClassISd=("Not Class I", "std"),
            unclassifiedMean=("Unclassified", "mean"),
            unclassifiedSd=("Unclassified", "std"),
            totalMean=("Total", "mean"),
            totalSd=("Total", "std"),
        )
        .fillna(0.0)
    )
    summary["Condition"] = pd.Categorical(summary["Condition"], categories=selected_conditions, ordered=True)
    summary = summary.sort_values("Condition").reset_index(drop=True)
    return counts, summary

def phospho_coverage_table(data, metadata, is_log2, include_id: bool = False, conditions: list[str] | None = None, mode: str = "Normal") -> pd.DataFrame:
    counts, summary = _coverage_counts(data, metadata, is_log2, include_id=include_id, conditions=conditions)
    return counts if str(mode).lower() == "normal" else summary

def _filter_meta_conditions(meta: pd.DataFrame, conditions: list[str] | None) -> tuple[pd.DataFrame, list[str]]:
    available = meta["condition"].astype(str).dropna().tolist()
    ordered_available = list(dict.fromkeys(available))
    if conditions:
        selected = [condition for condition in conditions if condition in ordered_available]
    else:
        selected = ordered_available
    if not selected:
        raise ValueError("No matching conditions available for phospho coverage plot.")
    filtered = meta[meta["condition"].isin(selected)].copy()
    if filtered.empty:
        raise ValueError("No phospho samples available for the selected conditions.")
    return filtered, selected

def phospho_distribution_table(data, cutoff: float = 0.0) -> pd.DataFrame:
    frame = data
    if "site_num" in frame.columns:
        site_counts = pd.to_numeric(frame["site_num"], errors="coerce").dropna()
    else:
        group_col = "Phosphoprotein" if "Phosphoprotein" in frame.columns else "Protein_group"
        if group_col not in frame.columns or "PTM_Collapse_key" not in frame.columns:
            raise ValueError("Phospho distribution requires site_num or (Phosphoprotein/Protein_group + PTM_Collapse_key).")
        site_counts = (
            frame.groupby(group_col)["PTM_Collapse_key"].nunique().astype(float)
        )

    if site_counts.empty:
        return pd.DataFrame({"SiteCount": [], "Frequency": []})

    if cutoff > 0:
        threshold = float(site_counts.quantile(1 - float(cutoff)))
        kept = site_counts[site_counts <= threshold]
        trimmed = int(len(site_counts) - len(kept))
        site_counts = kept
    else:
        threshold, trimmed = float("nan"), 0

    freq = site_counts.value_counts().sort_index()
    table = pd.DataFrame({"SiteCount": freq.index.astype(int), "Frequency": freq.values.astype(int)})
    # What the trim removed, for the plot's note; not a column, so the table
    # the page and the notebook show is unchanged.
    table.attrs["trimmed_proteins"] = trimmed
    table.attrs["trim_threshold"] = threshold
    return table

def phospho_sty_table(data, ) -> pd.DataFrame:
    frame = data
    if "PTM_Collapse_key" not in frame.columns:
        raise ValueError("Phospho dataset must contain PTM_Collapse_key for STY plot.")

    keys = frame["PTM_Collapse_key"].astype(str)
    # The site parser's rule: the residue is the letter before the position in
    # the last "_<residue><position>_M<n>" block, so a gene name that itself
    # contains "_T1" (restored into the key) cannot be read as the residue.
    letters = keys.str.extract(r"_([STY])\d+_M\d+$")[0]
    letters = letters.fillna(keys.str.extract(r"(?:^|_)([STY])\d+(?:_|$)")[0])

    counts = letters.value_counts().reindex(["S", "T", "Y"], fill_value=0)
    if letters.isna().any():
        counts.loc["Unparsed"] = int(letters.isna().sum())
    total = int(counts.sum())
    percentages = (counts / total * 100.0) if total > 0 else counts.astype(float)
    return pd.DataFrame(
        {
            "Residue": counts.index.tolist(),
            "Count": counts.values.astype(int),
            "Percentage": percentages.values.round(2),
        }
    )

def split_tokens(value) -> list[str]:
    """The `;`-separated members of a protein-group or gene-group cell."""
    text = str(value if value is not None else "").strip()
    if not text or text.lower() == "nan":
        return []
    return [token.strip() for token in text.replace(",", ";").split(";") if token.strip()]

def _gene_tokens(value: object) -> list[str]:
    """The members of a gene or protein-group cell: the shared `split_tokens`
    rule (`;` or `,` separated, blanks and NaN empty), so the app, the pip
    package and the R functions cut cells the same way (2026-10-22)."""
    if value is None or (not isinstance(value, str) and pd.isna(value)):
        return []
    return split_tokens(value)

def _normalize_identifier(identifier: str) -> str:
    normalized = str(identifier).strip().lower()
    if normalized == "genes":
        return "genes"
    return "workflow"

def _line_box_key_column_for_identifier(
    kind: str,
    frame: pd.DataFrame,
    identifier: str = "workflow",
) -> str:
    resolved_identifier = _normalize_identifier(identifier)
    if resolved_identifier == "genes":
        gene_candidates = ["GeneNames", "Gene_group"]
        for candidate in gene_candidates:
            if candidate in frame.columns:
                return candidate
        raise ValueError("Gene names are not available for this dataset.")

    if kind == "protein":
        candidates = ["ProteinNames", "Protein", "Gene"]
    else:
        candidates = ["PTM_Collapse_key", "Phosphoprotein", "Protein_group"]
    for candidate in candidates:
        if candidate in frame.columns:
            return candidate
    raise ValueError(
        f"Could not find a feature identifier column for {kind}. "
        f"Expected one of: {', '.join(candidates)}"
    )

def _build_sample_labels(meta: pd.DataFrame, include_id: bool) -> pd.DataFrame:
    labeled = meta.copy()
    labeled["sample"] = labeled["sample"].astype(str)
    labeled["condition"] = labeled["condition"].astype(str)
    labeled["new_sample"] = condition_sample_labels(labeled)
    if include_id:
        # The id goes on a second line so a long run name cannot widen the axis.
        ids = labeled["sample"].map(lambda sample: extract_sample_id(str(sample)))
        labeled["new_sample"] = labeled["new_sample"] + "\n(" + ids.astype(str) + ")"
    return labeled

def _feature_match_mask(
    values: pd.Series,
    selected: set[str],
    kind: str,
    identifier: str,
) -> pd.Series:
    text_values = values.astype(str)
    if identifier == "genes":
        selected_keys = {value.casefold() for value in selected}

        def _has_gene(value: str) -> bool:
            tokens = _gene_tokens(value)
            return any(token.casefold() in selected_keys for token in tokens)

        return text_values.apply(_has_gene)

    # Stripped, because _feature_options strips before it offers a value: an
    # unstripped compare here would make a legitimate selection match nothing.
    return text_values.str.strip().isin(selected)

def _select_conditions(meta: pd.DataFrame, conditions: list[str]) -> tuple[pd.DataFrame, list[str]]:
    available = meta["condition"].astype(str).dropna().tolist()
    unique_available = list(dict.fromkeys(available))
    if not conditions:
        selected = unique_available
    else:
        selected = [condition for condition in conditions if condition in unique_available]
    if not selected:
        raise ValueError("No matching conditions selected.")
    filtered = meta[meta["condition"].isin(selected)].copy()
    if filtered.empty:
        raise ValueError("No samples found for the selected conditions.")
    return filtered, selected

def _single_box_data(data, metadata,
    kind: str,
    protein: str,
    conditions: list[str],
    identifier: str = "workflow",
    data_source: str = "data",
) -> tuple[list[np.ndarray], list[str], dict[str, np.ndarray], pd.DataFrame]:
    if not str(protein).strip():
        raise ValueError("Please select one protein/site for the boxplot.")

    frame, meta = data, metadata
    sample_columns = [s for s in meta["sample"].astype(str) if s in frame.columns]
    resolved_identifier = _normalize_identifier(identifier)
    key_col = _line_box_key_column_for_identifier(kind, frame, identifier=resolved_identifier)
    workflow_col = key_col
    if resolved_identifier == "genes":
        try:
            workflow_col = _line_box_key_column_for_identifier(kind, frame, identifier="workflow")
        except ValueError:
            workflow_col = key_col
    selected_columns = list(dict.fromkeys([key_col, workflow_col, *sample_columns]))
    data = frame[selected_columns].copy()
    meta_filtered, _ = _select_conditions(meta, conditions)

    selected_set = {str(protein).strip()}
    mask = _feature_match_mask(data[key_col], selected_set, kind, resolved_identifier)
    selected_rows = data[mask].copy()
    if selected_rows.empty:
        raise ValueError("No row matched the selected protein/site.")

    labeled = _build_sample_labels(meta_filtered, include_id=False)
    rename_map = dict(zip(labeled["sample"], labeled["new_sample"]))
    selected_rows = selected_rows.rename(columns=rename_map)
    source_feature_count = int(len(selected_rows))
    source_features = "; ".join(
        sorted(
            {
                str(value).strip()
                for value in selected_rows[workflow_col].tolist()
                if str(value).strip()
            },
            key=str.casefold,
        )
    )
    aggregation_warning = ""
    if source_feature_count > 1:
        if resolved_identifier == "genes":
            aggregation_warning = (
                f"Combined {source_feature_count} source features mapped to this gene; "
                "each value is their per-sample median."
            )
        else:
            aggregation_warning = (
                f"Consolidated {source_feature_count} duplicate rows matching this feature; "
                "each value is their per-sample median."
            )

    condition_values: dict[str, np.ndarray] = {}
    for condition in labeled["condition"].astype(str).drop_duplicates().tolist():
        columns = labeled.loc[labeled["condition"] == condition, "new_sample"].tolist()
        present = [column for column in columns if column in selected_rows.columns]
        if not present:
            continue
        numeric = selected_rows[present].apply(pd.to_numeric, errors="coerce").replace(
            [np.inf, -np.inf], np.nan
        )
        values = numeric.median(axis=0, skipna=True).to_numpy(dtype=float)
        values = values[np.isfinite(values)]
        if values.size == 0:
            continue
        condition_values[condition] = values

    labels = list(condition_values.keys())
    intensities = [condition_values[label] for label in labels]
    summary_rows: list[dict[str, object]] = []
    for label, values in condition_values.items():
        q1 = float(np.percentile(values, 25))
        median = float(np.median(values))
        q3 = float(np.percentile(values, 75))
        summary_row: dict[str, object] = {
            "Condition": label,
            "N": int(values.size),
            "Mean": round(float(np.mean(values)), 4),
            "Median": round(median, 4),
            "Q1": round(q1, 4),
            "Q3": round(q3, 4),
            "Min": round(float(np.min(values)), 4),
            "Max": round(float(np.max(values)), 4),
        }
        summary_row.update(
            {
                "SampleCount": int(values.size),
                "SourceFeatureCount": source_feature_count,
                "SourceFeatures": source_features,
                "Aggregation": "Per-sample median",
                "Warning": aggregation_warning,
            }
        )
        summary_rows.append(summary_row)
    summary_df = pd.DataFrame(summary_rows)
    return intensities, labels, condition_values, summary_df

def condition_sample_labels(frame: pd.DataFrame) -> pd.Series:
    """``condition_N`` per row: N is the sample's 1-based place inside its condition.

    Every plot renames its sample columns this way. The expression was written
    out in six places, including inside `sample_label_frame`, whose whole job is
    to be the one copy the report's sample-mapping table can be trusted against.
    """
    return frame["condition"].astype(str) + "_" + (frame.groupby("condition").cumcount() + 1).astype(str)

def _feature_label(value: object, kind: str) -> str:
    return str(value).strip()

def _lineplot_long_table(data, metadata,
    kind: str,
    proteins: list[str],
    conditions: list[str],
    include_id: bool,
    identifier: str = "workflow",
    data_source: str = "data",
) -> tuple[pd.DataFrame, list[str]]:
    if not proteins:
        raise ValueError("Please select at least one protein/site for the lineplot.")

    frame, meta = data, metadata
    sample_columns = [s for s in meta["sample"].astype(str) if s in frame.columns]
    resolved_identifier = _normalize_identifier(identifier)
    key_col = _line_box_key_column_for_identifier(kind, frame, identifier=resolved_identifier)
    workflow_col = key_col
    if resolved_identifier == "genes":
        try:
            workflow_col = _line_box_key_column_for_identifier(kind, frame, identifier="workflow")
        except ValueError:
            # The gene itself remains a valid source identity when no separate
            # workflow identifier is present.
            workflow_col = key_col
    selected_columns = list(dict.fromkeys([key_col, workflow_col, *sample_columns]))
    data = frame[selected_columns].copy()

    meta_filtered, selected_conditions = _select_conditions(meta, conditions)
    labeled = _build_sample_labels(meta_filtered, include_id=include_id)
    rename_map = dict(zip(labeled["sample"], labeled["new_sample"]))
    ordered_samples: list[str] = []
    for condition in selected_conditions:
        ordered_samples.extend(labeled.loc[labeled["condition"] == condition, "new_sample"].tolist())

    data = data.rename(columns=rename_map)
    selected_set = {str(item).strip() for item in proteins if str(item).strip()}
    if not selected_set:
        raise ValueError("Please select at least one protein/site for the lineplot.")

    mask = _feature_match_mask(data[key_col], selected_set, kind, resolved_identifier)
    feature_rows = data[mask].copy()
    if feature_rows.empty:
        raise ValueError("No rows matched the selected proteins/sites.")

    available_plot_samples = [sample for sample in ordered_samples if sample in feature_rows.columns]
    if not available_plot_samples:
        raise ValueError("No sample columns available after condition filtering.")

    if resolved_identifier == "genes":
        selected_gene_labels = {
            value.casefold(): value
            for value in sorted(selected_set, key=str.casefold)
        }
        feature_rows["__source_row"] = np.arange(len(feature_rows), dtype=int)
        feature_rows["__feature_tokens"] = feature_rows[key_col].apply(
            lambda value: list(
                dict.fromkeys(
                    selected_gene_labels[token.casefold()]
                    for token in _gene_tokens(value)
                    if token.casefold() in selected_gene_labels
                )
            )
        )
        feature_rows = feature_rows.explode("__feature_tokens")
        feature_rows = feature_rows[feature_rows["__feature_tokens"].notna()].copy()
        if feature_rows.empty:
            raise ValueError("No rows matched the selected genes.")

        feature_metadata = (
            feature_rows.groupby("__feature_tokens", sort=True)
            .agg(
                SourceFeatureCount=("__source_row", "nunique"),
                SourceFeatures=(
                    workflow_col,
                    lambda values: "; ".join(
                        sorted(
                            {
                                str(value).strip()
                                for value in values
                                if str(value).strip()
                            },
                            key=str.casefold,
                        )
                    ),
                ),
            )
            .reset_index()
        )
        melted = feature_rows[["__feature_tokens"] + available_plot_samples].melt(
            id_vars="__feature_tokens",
            var_name="Sample",
            value_name="Value",
        )
        melted["Feature"] = melted["__feature_tokens"].astype(str)
        melted["Value"] = pd.to_numeric(melted["Value"], errors="coerce").replace(
            [np.inf, -np.inf], np.nan
        )
        melted = (
            melted.groupby(["Feature", "Sample"], as_index=False, sort=True)["Value"]
            .median()
        )
        melted = melted.merge(
            feature_metadata.rename(columns={"__feature_tokens": "Feature"}),
            on="Feature",
            how="left",
        )
        melted["SampleCount"] = melted.groupby("Feature")["Value"].transform("count")
        melted["Aggregation"] = "Per-sample median"
        melted["Warning"] = melted.apply(
            lambda row: (
                f"Combined {int(row['SourceFeatureCount'])} source features mapped to this gene; "
                "each plotted value is their per-sample median."
                if int(row["SourceFeatureCount"]) > 1
                else ""
            ),
            axis=1,
        )
    else:
        feature_rows["Feature"] = feature_rows[key_col].apply(
            lambda value: _feature_label(value, kind)
        )
        feature_rows["__source_row"] = np.arange(len(feature_rows), dtype=int)
        feature_metadata = (
            feature_rows.groupby("Feature", sort=True)
            .agg(
                SourceFeatureCount=("__source_row", "nunique"),
                SourceFeatures=(
                    workflow_col,
                    lambda values: "; ".join(
                        sorted(
                            {
                                str(value).strip()
                                for value in values
                                if str(value).strip()
                            },
                            key=str.casefold,
                        )
                    ),
                ),
            )
            .reset_index()
        )
        melted = feature_rows[["Feature"] + available_plot_samples].melt(
            id_vars="Feature",
            var_name="Sample",
            value_name="Value",
        )
        melted["Value"] = pd.to_numeric(melted["Value"], errors="coerce").replace(
            [np.inf, -np.inf], np.nan
        )
        melted = (
            melted.groupby(["Feature", "Sample"], as_index=False, sort=True)["Value"]
            .median()
        )
        melted = melted.merge(feature_metadata, on="Feature", how="left")
        melted["SampleCount"] = melted.groupby("Feature")["Value"].transform("count")
        melted["Aggregation"] = "Per-sample median"
        melted["Warning"] = melted.apply(
            lambda row: (
                f"Consolidated {int(row['SourceFeatureCount'])} duplicate rows for this feature; "
                "each plotted value is their per-sample median."
                if int(row["SourceFeatureCount"]) > 1
                else ""
            ),
            axis=1,
        )

    melted["Value"] = pd.to_numeric(melted["Value"], errors="coerce").replace(
        [np.inf, -np.inf], np.nan
    )
    melted = melted.merge(
        labeled[["new_sample", "condition"]].rename(columns={"new_sample": "Sample", "condition": "Condition"}),
        on="Sample",
        how="left",
    )
    order_index = {sample: idx for idx, sample in enumerate(available_plot_samples)}
    melted["x"] = melted["Sample"].map(order_index)
    melted = melted.sort_values(["Feature", "x"]).reset_index(drop=True)
    return melted, available_plot_samples

def single_protein_lineplot_table(data, metadata,
    kind: str,
    proteins: list[str],
    conditions: list[str],
    include_id: bool = False,
    identifier: str = "workflow",
    data_source: str = "data",
) -> pd.DataFrame:
    table, _ = _lineplot_long_table(data, metadata,
        kind,
        proteins,
        conditions,
        include_id=include_id,
        identifier=identifier,
        data_source=data_source,
    )
    columns = ["Feature", "Sample", "Condition", "Value"]
    for column in (
        "SampleCount",
        "SourceFeatureCount",
        "SourceFeatures",
        "Aggregation",
        "Warning",
    ):
        if column in table.columns:
            columns.append(column)
    result = table[columns].copy()
    result["Value"] = result["Value"].round(4)
    return result

def intensity_unit_label(centered=False, scale="log2", workflow=""):
    unit = "Ratio to Site Median" if centered else "Intensity"
    return " ".join(part for part in (scale, workflow, unit) if part)

def _site_label(site_key: object, filter_m1: bool) -> str:
    """The short row label the heatmap draws for one phosphosite.

    `A0A590UK10~ARHGEF18_S1035_M1` becomes `ARHGEF18_S1035_M1`, and `_M1` comes
    off as well when the view is already filtered to multiplicity 1, because
    then it is the same on every row. This is a display label: it drops the
    protein accession, so it is not a collapse key and must never be exported
    under that name.
    """
    text = str(site_key)
    if "~" in text:
        text = text.split("~", maxsplit=1)[1]
    if filter_m1 and text.endswith("_M1"):
        text = text.rsplit("_", maxsplit=1)[0]
    return text

def _heatmap_protein_group_column(frame: pd.DataFrame) -> str:
    for candidate in ["Protein_group", "ProteinNames", "Phosphoprotein"]:
        if candidate in frame.columns:
            return candidate
    raise ValueError(
        "Could not find a protein-group column for phosphosite heatmap. "
        "Expected one of: Protein_group, ProteinNames, Phosphoprotein."
    )

def _heatmap_key_column_for_identifier(
    frame: pd.DataFrame,
    identifier: str = "workflow",
) -> str:
    resolved_identifier = _normalize_identifier(identifier)
    if resolved_identifier == "genes":
        for candidate in ["GeneNames", "Gene_group"]:
            if candidate in frame.columns:
                return candidate
        raise ValueError("Gene names are not available for this phospho dataset.")
    return _heatmap_protein_group_column(frame)

def _heatmap_matrix(data, metadata,
    kind: str,
    protein: str,
    conditions: list[str],
    include_id: bool,
    filter_m1: bool,
    cluster_rows: bool,
    cluster_cols: bool,
    value_type: str,
    identifier: str = "workflow",
    data_source: str = "data",
) -> tuple[pd.DataFrame, str]:
    if kind != "phospho":
        raise ValueError("Phosphosite-on-protein heatmap is only available for phospho dataset.")
    if not str(protein).strip():
        raise ValueError("Please select a protein for the heatmap.")

    frame, meta = data, metadata
    resolved_identifier = _normalize_identifier(identifier)
    key_col = _heatmap_key_column_for_identifier(frame, identifier=resolved_identifier)
    if "PTM_Collapse_key" not in frame.columns:
        raise ValueError("Phospho dataset is missing PTM_Collapse_key column.")

    # The same matcher as the boxplot and the lineplot. This used to be a
    # case-insensitive substring search on the protein-group column, which
    # merged every accession the selection is a prefix of -- an isoform group
    # `P12345-2`, or the group `P12345;Q67890` -- into one heatmap, under the
    # label of the one protein the user picked. The selector offers whole
    # values from this column, so an exact match reaches everything it can
    # reach, and a stale selection now says so instead of drawing something
    # else.
    selected_value = str(protein).strip()
    mask = _feature_match_mask(
        frame[key_col], {selected_value}, kind="phospho", identifier=resolved_identifier
    )
    protein_data = frame[mask].copy()

    if protein_data.empty:
        entity_label = "gene" if resolved_identifier == "genes" else "protein"
        raise ValueError(f"No phosphosite rows found for {entity_label} '{selected_value}'.")

    meta_filtered, _ = _select_conditions(meta, conditions)
    labeled = _build_sample_labels(meta_filtered, include_id=include_id)
    sample_cols = [sample for sample in labeled["sample"].astype(str).tolist() if sample in protein_data.columns]
    if not sample_cols:
        raise ValueError("No sample columns available for selected conditions.")

    if filter_m1:
        protein_data = protein_data[
            protein_data["PTM_Collapse_key"].astype(str).str.endswith("_M1", na=False)
        ]
        if protein_data.empty:
            raise ValueError("No phosphosite rows remain after filtering to *_M1 entries.")

    rename_map = dict(zip(labeled["sample"], labeled["new_sample"]))
    matrix = protein_data.set_index("PTM_Collapse_key")[sample_cols].rename(columns=rename_map)
    total_features = len(matrix)
    matrix = matrix.apply(pd.to_numeric, errors="coerce")
    matrix = matrix.dropna(how="all")
    if matrix.empty:
        raise ValueError("No numeric phosphosite values available for the selected settings.")

    # The index stays the full PTM_Collapse_key from here on. The heatmap draws
    # the short site label, because every row belongs to the one protein the
    # user selected and repeating its accession down the axis says nothing --
    # but the table keeps the whole identifier, so an exported row can be traced
    # back to the matrix it came from. Full keys are also unique, which the
    # short labels are not guaranteed to be.
    value_type_normalized = str(value_type).lower()
    if value_type_normalized == "z":
        matrix = pd.DataFrame(row_zscore(matrix), index=matrix.index, columns=matrix.columns)
        cbar_label = "Z-score"
    elif value_type_normalized == "log2":
        cbar_label = intensity_unit_label(False)
    else:
        raise ValueError("valueType must be 'log2' or 'z'.")

    # Remove undefined rows before clustering. The shared z-score helper keeps
    # constant rows as zero; they remain valid heatmap rows.
    matrix = matrix.replace([np.inf, -np.inf], np.nan).dropna(how="all")
    if matrix.empty:
        raise ValueError("Heatmap matrix is empty after preprocessing.")

    cluster_matrix = None
    if (cluster_rows and matrix.shape[0] > 1) or (cluster_cols and matrix.shape[1] > 1):
        cluster_matrix, completeness = drop_incomplete_features(
            matrix,
            context="single-protein heatmap",
        )
        matrix = matrix.loc[completeness.kept]

    if cluster_rows and matrix.shape[0] > 1:
        try:
            from scipy.cluster.hierarchy import leaves_list, linkage
        except ModuleNotFoundError as exc:
            raise ModuleNotFoundError(
                "scipy is required for row clustering. Install it with: pip install scipy"
            ) from exc
        row_linkage = linkage(cluster_matrix, method="average", metric="euclidean")
        row_order = leaves_list(row_linkage)
        matrix = matrix.iloc[row_order]
        cluster_matrix = cluster_matrix[row_order]

    if cluster_cols and matrix.shape[1] > 1:
        try:
            from scipy.cluster.hierarchy import leaves_list, linkage
        except ModuleNotFoundError as exc:
            raise ModuleNotFoundError(
                "scipy is required for column clustering. Install it with: pip install scipy"
            ) from exc
        col_linkage = linkage(cluster_matrix.T, method="average", metric="euclidean")
        matrix = matrix.iloc[:, leaves_list(col_linkage)]
    matrix.attrs["heatmap_notice"] = heatmap_notice(total_features, len(matrix), noun="phosphosites")
    return matrix, cbar_label

def single_protein_heatmap_table(data, metadata,
    kind: str,
    protein: str,
    conditions: list[str],
    identifier: str = "workflow",
    include_id: bool = False,
    filter_m1: bool = True,
    cluster_rows: bool = False,
    cluster_cols: bool = False,
    value_type: str = "log2",
    data_source: str = "data",
) -> pd.DataFrame:
    matrix, _ = _heatmap_matrix(data, metadata,
        kind=kind,
        protein=protein,
        conditions=conditions,
        include_id=include_id,
        filter_m1=filter_m1,
        cluster_rows=cluster_rows,
        cluster_cols=cluster_cols,
        value_type=value_type,
        identifier=identifier,
        data_source=data_source,
    )
    # Two label columns, both honest: `Site` is what the plot draws, so a row
    # here can be found on the figure, and `PTM_Collapse_key` is the whole
    # identifier the value was read under. The header used to say
    # `PTM_Collapse_key` over the short label -- a `rename(columns={"index":
    # ...})` that never fired, because reset_index restores the index's own
    # name -- so the exported accession was simply missing.
    keys = matrix.index.astype(str)
    table = matrix.reset_index(drop=True)
    table.insert(0, "PTM_Collapse_key", keys)
    table.insert(0, "Site", [_site_label(key, filter_m1) for key in keys])
    label_cols = {"Site", "PTM_Collapse_key"}
    numeric_cols = [col for col in table.columns if col not in label_cols]
    table[numeric_cols] = table[numeric_cols].round(4)
    return table

from dataclasses import dataclass

def heatmap_notice(total: int, used: int, *, noun: str = "features") -> str:
    percent = used / total * 100 if total else 0
    message = f"Heatmap-usable {noun}: {used:,} of {total:,} ({percent:.1f}%)"
    if used < total:
        message += (
            f"; {total - used:,} excluded because of missing or undefined values "
            "in the selected samples after preprocessing"
        )
    return message

@dataclass(frozen=True)
class CompletenessReport:
    """How many features a projection or clustering could actually use.

    Hierarchical clustering and PCA are undefined on a feature that is missing in
    any sample, so those features are excluded. Excluding them silently is the
    real hazard: the projection then rests on a smaller, abundance-biased subset
    and nothing says so. The count travels back with the result so the interface
    can state it in a notice beneath the plot.
    """

    kept: np.ndarray
    dropped: int
    total: int

    @property
    def any_dropped(self) -> bool:
        return self.dropped > 0

    @property
    def percent(self) -> float:
        return (self.dropped / self.total * 100.0) if self.total else 0.0

def drop_incomplete_features(
    matrix: pd.DataFrame | np.ndarray,
    *,
    context: str = "heatmap",
    minimum_rows: int = 1,
) -> tuple[np.ndarray, CompletenessReport]:
    """Return the fully observed rows, plus what that cost.

    Replaces the previous behaviour of refusing the whole matrix when any value
    was missing. On the bundled HEK293 data that refusal cost the entire protein
    ANOVA heatmap because 27 of 2,908 features were incomplete, and the remedy it
    suggested -- disabling clustering -- was not reachable from the interface.

    Raises only when nothing usable is left, which is a real failure rather than
    a reportable one.
    """
    if isinstance(matrix, pd.DataFrame):
        numeric = matrix.apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    else:
        numeric = np.asarray(matrix, dtype=float)
    if numeric.ndim != 2:
        raise ValueError("Clustering requires a two-dimensional matrix.")

    rows, columns = numeric.shape
    complete = np.isfinite(numeric).all(axis=1)
    kept_count = int(complete.sum())

    if kept_count < max(1, minimum_rows):
        raise ValueError(
            f"{context.capitalize()} cannot be computed because only {kept_count} of "
            f"{rows} features are observed in all {columns} samples. Run Imputation "
            "successfully and select 'Imputed Data', or relax the completeness "
            "filter. The data source was not changed automatically."
        )

    return numeric[complete], CompletenessReport(
        kept=complete, dropped=rows - kept_count, total=rows
    )

def row_zscore(matrix):
    """Row-wise z-scores with the sample standard deviation (ddof=1).

    One definition for every heatmap: the ANOVA heatmaps used the population
    SD (ddof=0) while the pathway and phosphosite heatmaps used ddof=1, and all
    three said "z-score". ddof=1 is the convention of the tool's other
    statistics and of the R functions. A row with no spread (or a non-finite SD)
    is centred and left at zero rather than made undefined, as R does.
    """
    values = np.asarray(matrix, dtype=float)
    row_mean = np.nanmean(values, axis=1, keepdims=True)
    row_sd = np.nanstd(values, axis=1, ddof=1, keepdims=True)
    row_sd[(row_sd == 0) | ~np.isfinite(row_sd)] = 1.0
    return (values - row_mean) / row_sd

def single_protein_boxplot_table(data, metadata, kind, protein, conditions, identifier='workflow', data_source='data'):
    return _single_box_data(data, metadata, kind, protein, conditions, identifier, data_source)[3]

def _renamed_meta(meta: pd.DataFrame, include_id: bool = True) -> pd.DataFrame:
    renamed = meta.copy()
    renamed["sample"] = renamed["sample"].astype(str)
    renamed["id"] = renamed["sample"].apply(extract_sample_id)
    renamed["new_sample"] = renamed.groupby("condition").cumcount() + 1
    if include_id:
        renamed["new_sample"] = renamed.apply(
            lambda row: f"{row['condition']}_{row['new_sample']} ({row['id']})",
            axis=1,
        )
    else:
        renamed["new_sample"] = renamed.apply(
            lambda row: f"{row['condition']}_{row['new_sample']}",
            axis=1,
        )
    return renamed

def _selected_matrix(
    frame: pd.DataFrame, meta: pd.DataFrame, include_id: bool = True
) -> tuple[pd.DataFrame, pd.DataFrame, int]:
    """The annotated sample columns, without features missing in all of them.

    A row with no value in any selected sample says nothing about the
    completeness of those samples (it was identified elsewhere, or never
    quantified), so it is excluded once here for the missing-value plot, the
    heatmap and the summary tables alike -- the same rule the coverage plots
    apply to their reference line. The number of excluded rows is returned so
    the page and the report can state it.
    """
    renamed_meta = _renamed_meta(meta, include_id=include_id)
    rename_map = dict(zip(renamed_meta["sample"], renamed_meta["new_sample"]))
    filtered = frame.rename(columns=rename_map)
    columns = [c for c in renamed_meta["new_sample"].tolist() if c in filtered.columns]
    if not columns:
        raise ValueError("No metadata sample columns are present in the dataset.")
    matrix = filtered[columns]
    present = matrix.notna().any(axis=1)
    excluded = int((~present).sum())
    return matrix[present], renamed_meta, excluded

def _filtered_data(frame: pd.DataFrame, meta: pd.DataFrame, include_id: bool = True) -> tuple[pd.DataFrame, pd.DataFrame]:
    matrix, renamed_meta, _excluded = _selected_matrix(frame, meta, include_id=include_id)
    return matrix, renamed_meta

def completeness_sample_summary_table(
    frame: pd.DataFrame, meta: pd.DataFrame,
    include_id: bool = True,
) -> pd.DataFrame:
    data_filtered, _ = _filtered_data(frame, meta, include_id=include_id)

    na_counts = data_filtered.isna().sum(axis=0)
    summary = na_counts.reset_index()
    summary.columns = ["Sample", "Counts"]
    total_rows = max(1, data_filtered.shape[0])
    summary["%_missing_values"] = (summary["Counts"] / total_rows) * 100.0
    summary["%_missing_values"] = summary["%_missing_values"].round(2)
    return summary

def completeness_feature_summary_table(
    frame: pd.DataFrame, meta: pd.DataFrame,
    include_id: bool = True,
) -> pd.DataFrame:
    data_filtered, _ = _filtered_data(frame, meta, include_id=include_id)

    na_counts = data_filtered.isna().sum(axis=1)
    summary = na_counts.value_counts().reset_index()
    summary.columns = ["n_MissingProteinValues", "Counts"]
    summary = summary.sort_values("n_MissingProteinValues").reset_index(drop=True)
    total_counts = max(1, int(summary["Counts"].sum()))
    summary["%_missing_values"] = ((summary["Counts"] / total_counts) * 100.0).round(2)
    return summary

def summarize_peptide_coverage(data_filtered, meta):
    selected = list(data_filtered.columns)
    summary = data_filtered.notna().sum(axis=0).reset_index()
    summary.columns = ["Sample", "Value"]
    summary["Sample"] = pd.Categorical(summary["Sample"], categories=selected, ordered=True)
    summary = summary.sort_values("Sample")
    # Reference line: features quantified in at least one selected sample -- the
    # union of the bars, as on the protein coverage plot (_feature_context).
    # The pivot row count also holds sequences that were identified but never
    # quantified, or quantified only in runs outside the annotation.
    peptides_count = int(data_filtered.notna().any(axis=1).sum())

    return summary, peptides_count, meta

def peptide_coverage_table(data, metadata):
    return summarize_peptide_coverage(data, metadata)[0]

PEPTIDE_MODIFICATION_PATTERNS: dict[str, re.Pattern[str]] = {
    "Carbamidomethylation": re.compile(
        r"(?:UniMod:4(?!\d)|(?<![A-Za-z])Carbamidomethyl(?:ation)?(?![A-Za-z]))",
        re.IGNORECASE,
    ),
    "Oxidation": re.compile(
        r"(?:UniMod:35(?!\d)|(?<![A-Za-z])Oxidation(?![A-Za-z]))",
        re.IGNORECASE,
    ),
    "Acetylation": re.compile(
        r"(?:UniMod:1(?!\d)|(?<![A-Za-z])Acetyl(?:ation)?(?![A-Za-z]))",
        re.IGNORECASE,
    ),
}

def peptide_modification_counts(
    frame: pd.DataFrame,
    *,
    sequence_column: str,
    sample_columns: list[str],
) -> pd.DataFrame:
    """Count detected modified sequences per sample using shared exact classifiers.

    Each sequence contributes at most once to a modification class in a sample,
    even if the sequence contains that modification more than once. A sequence
    carrying multiple tracked classes contributes once to each relevant class
    but only once to ``UniqueTrackedModifiedPeptides``.
    """
    if sequence_column not in frame.columns:
        raise ValueError("Modified sequence column is missing.")
    missing_samples = [column for column in sample_columns if column not in frame.columns]
    if missing_samples:
        raise ValueError("Modification count sample columns are missing from the peptide table.")

    sequences = frame[sequence_column].fillna("").astype(str)
    quantities = frame[sample_columns].apply(pd.to_numeric, errors="coerce")
    quantities = quantities.replace([np.inf, -np.inf], np.nan).replace(0, np.nan)
    detected = quantities.notna()
    detected_by_sequence = detected.groupby(sequences, sort=False).any()
    unique_sequences = pd.Series(
        detected_by_sequence.index.astype(str),
        index=detected_by_sequence.index,
        dtype="string",
    )

    counts = pd.DataFrame(index=sample_columns, dtype="int64")
    matched_masks: list[pd.Series] = []
    for modification, pattern in PEPTIDE_MODIFICATION_PATTERNS.items():
        matched = unique_sequences.str.contains(pattern, na=False)
        matched_masks.append(matched)
        counts[modification] = (
            detected_by_sequence.loc[matched].sum(axis=0).astype("int64")
        )

    any_tracked = (
        pd.concat(matched_masks, axis=1).any(axis=1)
        if matched_masks
        else pd.Series(False, index=detected_by_sequence.index)
    )
    counts["UniqueTrackedModifiedPeptides"] = (
        detected_by_sequence.loc[any_tracked].sum(axis=0).astype("int64")
    )
    counts.index.name = "Sample"
    return counts

from typing import Literal

PeptideProtease = Literal["trypsin", "trypsin_lysc"]

_PROTEASE_PROLINE_BLOCKED: dict[str, dict[str, bool]] = {
    "trypsin": {"K": True, "R": True},
    "trypsin_lysc": {"K": False, "R": True},
}

def normalize_protease(value: object) -> PeptideProtease:
    key = str(value or "trypsin").strip().lower().replace("-", "_").replace("/", "_")
    key = key.replace("__", "_")
    if key in {"trypsin_lysc", "trypsin_lys_c", "trypsinlysc"}:
        return "trypsin_lysc"
    if key == "trypsin":
        return "trypsin"
    raise ValueError("Protease must be 'trypsin' or 'trypsin_lysc'.")

def count_missed_cleavages(sequence: object, protease: object = "trypsin") -> int:
    """Count internal missed cleavage sites in a peptide sequence.

    A missed cleavage is a cleavable residue that is neither the C-terminal
    residue -- that one is the expected cut site, not a missed one -- nor
    blocked by a following proline. Proline blocking is protease dependent, so
    it is looked up rather than assumed; see _PROTEASE_PROLINE_BLOCKED.
    """
    rules = _PROTEASE_PROLINE_BLOCKED[normalize_protease(protease)]
    residues = str(sequence or "").strip().upper()
    total = 0
    for index in range(len(residues) - 1):
        proline_blocked = rules.get(residues[index])
        if proline_blocked is None:
            continue
        if proline_blocked and residues[index + 1] == "P":
            continue
        total += 1
    return total

def peptide_missed_cleavage_summary(
    frame: pd.DataFrame,
    *,
    sequence_column: str,
    sample_columns: list[str],
    protease: object = "trypsin",
) -> pd.DataFrame:
    """Summarize detected unique peptide sequences by missed-cleavage count."""
    resolved_protease = normalize_protease(protease)
    if sequence_column not in frame.columns:
        raise ValueError("Stripped sequence column is missing.")
    missing_samples = [column for column in sample_columns if column not in frame.columns]
    if missing_samples:
        raise ValueError("Missed-cleavage sample columns are missing from the peptide table.")

    sequences = frame[sequence_column].fillna("").astype(str).str.strip()
    quantities = frame[sample_columns].apply(pd.to_numeric, errors="coerce")
    quantities = quantities.replace([np.inf, -np.inf], np.nan).replace(0, np.nan)
    detected_by_sequence = quantities.notna().groupby(sequences, sort=False).any()
    detected_by_sequence = detected_by_sequence.loc[detected_by_sequence.index != ""]

    columns = ["Sample", "Count", "Occurrences", "Total", "Percentage"]
    if detected_by_sequence.empty:
        return pd.DataFrame(columns=columns)

    cleavage_counts = pd.Series(
        [
            count_missed_cleavages(sequence, resolved_protease)
            for sequence in detected_by_sequence.index
        ],
        index=detected_by_sequence.index,
        dtype="int64",
    )
    detected_counts = detected_by_sequence.astype("int64").mul(cleavage_counts, axis=0)
    long = (
        detected_counts.where(detected_by_sequence)
        .reset_index(names=sequence_column)
        .melt(id_vars=sequence_column, var_name="Sample", value_name="Count")
        .dropna(subset=["Count"])
    )
    if long.empty:
        return pd.DataFrame(columns=columns)

    long["Count"] = long["Count"].astype("int64")
    summary = long.groupby(["Sample", "Count"]).size().reset_index(name="Occurrences")
    summary["Total"] = summary.groupby("Sample")["Occurrences"].transform("sum")
    summary["Percentage"] = (summary["Occurrences"] / summary["Total"]) * 100.0
    return summary[columns]

from scipy.cluster.hierarchy import leaves_list, linkage

from scipy.spatial.distance import pdist

def _first_available_column(frame: pd.DataFrame, candidates: list[str]) -> str | None:
    for column in candidates:
        if column in frame.columns:
            return column
    return None

def _gene_label_candidates(kind: str) -> list[str]:
    if kind == "phosprot":
        return ["Gene_group", "GeneNames"]
    return ["GeneNames", "Gene_group"]

def _aggregate_pathway_gene_values(
    frame: pd.DataFrame,
    *,
    gene_column: str,
    sample_columns: list[str],
    pathway_genes: list[str],
) -> tuple[pd.DataFrame, pd.Series]:
    """Collapse mapped features to one row per pathway gene by sample median."""
    value_frame = (
        frame.loc[:, sample_columns]
        .apply(pd.to_numeric, errors="coerce")
        .replace([np.inf, -np.inf], np.nan)
    )

    gene_positions: dict[str, list[int]] = {}
    for position, gene_value in enumerate(frame[gene_column].tolist()):
        # A repeated token within one annotation still represents one source
        # feature and must not increase its contribution count.
        row_tokens = {token.casefold() for token in _gene_tokens(gene_value)}
        for token in row_tokens:
            gene_positions.setdefault(token, []).append(position)

    ordered_genes: list[str] = []
    seen_genes: set[str] = set()
    for gene_value in pathway_genes:
        gene = str(gene_value).strip()
        gene_key = gene.casefold()
        if not gene or gene_key in seen_genes:
            continue
        seen_genes.add(gene_key)
        ordered_genes.append(gene)

    matrix_rows: list[pd.Series] = []
    source_counts: list[int] = []
    for gene in ordered_genes:
        positions = gene_positions.get(gene.casefold(), [])
        source_counts.append(len(positions))
        if not positions:
            matrix_rows.append(pd.Series(np.nan, index=sample_columns, dtype=float))
            continue
        matrix_rows.append(value_frame.iloc[positions].median(axis=0, skipna=True))

    heatmap_data = pd.DataFrame(matrix_rows, index=ordered_genes, columns=sample_columns)
    feature_counts = pd.Series(
        source_counts,
        index=ordered_genes,
        dtype="int64",
        name="source_feature_count",
    )
    return heatmap_data, feature_counts

def _pathway_matrix(data, metadata, database, *, centered=False,
    kind: str,
    pathway: str,
    conditions: list[str],
    value_type: str,
    include_id: bool,
    remove_empty: bool,
    cluster_rows: bool,
    cluster_cols: bool,
    show_source_count: bool = False,
    organism: str = "human",
):
    frame = data
    gene_column = _first_available_column(frame, _gene_label_candidates(kind))
    if gene_column is None:
        raise ValueError("A gene label column is required for pathway heatmaps.")

    db = database
    pathway_row = db.loc[db["description"].astype(str).str.lower() == pathway.strip().lower()]
    if pathway_row.empty:
        raise ValueError(f"No pathway found matching '{pathway}'.")
    pathway_genes = [gene.strip() for gene in str(pathway_row.iloc[0]["genes"]).split(";") if gene.strip()]
    if not pathway_genes:
        raise ValueError("The selected pathway does not contain any genes.")

    meta_filtered = metadata.copy()
    if conditions:
        meta_filtered = meta_filtered[meta_filtered["condition"].isin(conditions)]
    if meta_filtered.empty:
        raise ValueError("No samples match the selected conditions.")

    sample_columns = meta_filtered["sample"].astype(str).tolist()
    heatmap_data, source_feature_counts = _aggregate_pathway_gene_values(
        frame,
        gene_column=gene_column,
        sample_columns=sample_columns,
        pathway_genes=pathway_genes,
    )
    total_genes = len(heatmap_data)
    if remove_empty:
        heatmap_data = heatmap_data.dropna(how="all")
        source_feature_counts = source_feature_counts.loc[heatmap_data.index]
    if heatmap_data.empty:
        raise ValueError("No matching pathway genes were found in the current dataset.")

    if value_type == "z":
        heatmap_data = pd.DataFrame(
            row_zscore(heatmap_data), index=heatmap_data.index, columns=heatmap_data.columns
        )
        color_label = "Z-score"
    else:
        color_label = intensity_unit_label(centered)

    heatmap_data = heatmap_data.replace([np.inf, -np.inf], np.nan)
    if value_type == "z":
        heatmap_data = heatmap_data.dropna(how="all")
    if heatmap_data.empty:
        raise ValueError("No informative pathway rows remain after heatmap transformation.")

    if show_source_count:
        # How many dataset rows collapsed onto each gene. Off by default: on a
        # pathway of forty genes it is forty parentheticals down the side of the
        # figure, and for most of them the answer is 1.
        heatmap_data.index = [
            f"{gene} (n={int(source_feature_counts.loc[gene])})"
            for gene in heatmap_data.index
        ]

    meta_filtered = meta_filtered.reset_index(drop=True)
    # Keep pathway heatmap sample labels aligned with the app-wide convention:
    # condition + running number, with optional original sample id.
    meta_filtered["condition"] = meta_filtered["condition"].astype(str)
    meta_filtered["sample_index"] = meta_filtered.groupby("condition").cumcount() + 1
    if include_id:
        meta_filtered["display"] = meta_filtered.apply(
            lambda row: (
                f"{row['condition']}_{int(row['sample_index'])}\n"
                f"({extract_sample_id(row['sample'])})"
            ),
            axis=1,
        )
    else:
        meta_filtered["display"] = meta_filtered.apply(
            lambda row: f"{row['condition']}_{int(row['sample_index'])}",
            axis=1,
        )
    label_map = dict(zip(meta_filtered["sample"].astype(str), meta_filtered["display"]))
    heatmap_data = heatmap_data.rename(columns=label_map)

    cluster_matrix = None
    if (cluster_rows and heatmap_data.shape[0] > 1) or (cluster_cols and heatmap_data.shape[1] > 1):
        cluster_matrix, pathway_completeness = drop_incomplete_features(
            heatmap_data, context="pathway heatmap"
        )
        heatmap_data = heatmap_data.loc[pathway_completeness.kept]
    if cluster_rows and heatmap_data.shape[0] > 1:
        row_order = leaves_list(linkage(pdist(cluster_matrix), method="average"))
        heatmap_data = heatmap_data.iloc[row_order]
        cluster_matrix = cluster_matrix[row_order]
    if cluster_cols and heatmap_data.shape[1] > 1:
        col_order = leaves_list(linkage(pdist(cluster_matrix.T), method="average"))
        heatmap_data = heatmap_data.iloc[:, col_order]

    return heatmap_data, total_genes, color_label

def _ora_export_rows(result, request, direction):
    context = dict(method='ORA', organism=result['organism'], analysisSource=request['source'],
                   datasetLevel=result['kind'], dataSource=result['sourceUsed'])
    context.update({key: result[key] for key in ('backgroundMode', 'backgroundSize',
        'annotatedBackgroundSize', 'correctionMethod', 'upstreamCorrectionMethod', 'testedTermCount')})
    context.update(result['termCounts'][direction])
    if direction == 'cluster':
        keys = ['selectedCluster', 'pValueThreshold', 'useUncorrected', 'nClusters', 'clusterMethod']
    else:
        context.update(direction=direction, condition1=request['condition1'], condition2=request['condition2'],
            condition1Control=request['condition1Control'] if request['source'] == 'volcano_control' else '',
            condition2Control=request['condition2Control'] if request['source'] == 'volcano_control' else '')
        keys = ['testType', 'pValueThreshold', 'log2fcThreshold', 'useUncorrected']
    keys += ['adjPValueCutoff', 'minTermSize', 'maxTermSize']
    context.update({key: request[key] for key in keys})
    rows = []
    for term in result[f'{direction}Terms']:
        row = dict(context, ontology=term['source'])
        row.update({key: value for key, value in term.items() if key != 'source'})
        row['intersectingGenes'] = ','.join(term['intersectingGenes'])
        rows.append(row)
    return rows

from types import SimpleNamespace

from scipy.stats import hypergeom

def _bh_adjust(pvalues: np.ndarray) -> np.ndarray:
    """Benjamini-Hochberg adjusted p-values; NaN in, NaN out, others adjusted among themselves."""
    pvalues = np.asarray(pvalues, dtype=float)
    if pvalues.size == 0:
        return pvalues
    finite = np.isfinite(pvalues)
    if not finite.all():
        result = np.full(pvalues.shape, np.nan)
        result[finite] = _bh_adjust(pvalues[finite])
        return result
    order = np.argsort(pvalues)
    ranked = pvalues[order]
    n = float(len(ranked))
    adjusted_ranked = ranked * n / np.arange(1.0, n + 1.0)
    adjusted_ranked = np.minimum.accumulate(adjusted_ranked[::-1])[::-1]
    adjusted = np.empty_like(adjusted_ranked)
    adjusted[order] = np.clip(adjusted_ranked, 0.0, 1.0)
    return adjusted

def prepare_universe(database,
    background_genes: list[str] | None,
    min_term_size: int,
    max_term_size: int,
    organism: str = "human",
) -> tuple[set[str], list[tuple[str, str, str, set[str]]]]:
    records: list[tuple[str, str, str, set[str]]] = []
    annotated_genes: set[str] = set()
    db = database
    for ontology, term_id, description, genes_text in db[
        ["ontology", "term", "description", "genes"]
    ].itertuples(index=False, name=None):
        term_genes = {
            gene.strip()
            for gene in str(genes_text or "").split(";")
            if gene.strip()
        }
        annotated_genes.update(term_genes)
        records.append(
            (
                str(ontology or ""),
                str(term_id or ""),
                str(description or ""),
                term_genes,
            )
        )

    if background_genes is None:
        background = annotated_genes
    else:
        background = annotated_genes.intersection(
            {
                gene.strip()
                for gene in background_genes
                if gene and gene.strip()
            }
        )
    if not background:
        return set(), []

    eligible_terms: list[tuple[str, str, str, set[str]]] = []
    for ontology, term_id, description, term_genes in records:
        effective_term_genes = background.intersection(term_genes)
        if min_term_size <= len(effective_term_genes) <= max_term_size:
            eligible_terms.append(
                (ontology, term_id, description, effective_term_genes)
            )
    return background, eligible_terms

def _enrichment_terms(
    gene_list: list[str],
    top_n: int,
    adj_p_value_cutoff: float | None,
    background: set[str],
    eligible_terms: list[tuple[str, str, str, set[str]]],
    counts: dict[str, int] | None = None,
) -> list[SimpleNamespace]:
    if counts is not None:
        counts.update(searchSpace=len(eligible_terms), overlapTested=0, passingCutoff=0, displayed=0)
    genes = {
        gene.strip()
        for gene in gene_list
        if gene and gene.strip()
    }
    query = genes.intersection(background)
    if not query or not eligible_terms:
        return []

    population_size = len(background)
    sample_size = len(query)
    # Only terms sharing at least one gene with the query are tested. A term with
    # no overlap has p = 1 by construction and is never reported, so counting it
    # in the BH denominator would penalise every reported term for a test that
    # never ran. clusterProfiler draws the line in the same place.
    tested = [
        (term, overlap)
        for term, overlap in (
            (term, sorted(query.intersection(term[3]))) for term in eligible_terms
        )
        if overlap
    ]
    if not tested:
        return []
    if counts is not None:
        counts["overlapTested"] = len(tested)

    term_sizes = np.asarray([len(term[3]) for term, _ in tested], dtype=int)
    overlap_sizes = np.asarray([len(overlap) for _, overlap in tested], dtype=int)
    pvalues = np.asarray(
        hypergeom.sf(
            overlap_sizes - 1,
            population_size,
            term_sizes,
            sample_size,
        ),
        dtype=float,
    )
    adj = _bh_adjust(pvalues)
    terms: list[SimpleNamespace] = []
    for idx, ((ontology, term_id, description, term_genes), overlap) in enumerate(tested):
        p_value = float(pvalues[idx])
        adj_p_value = float(adj[idx])
        if adj_p_value_cutoff is not None and adj_p_value > float(adj_p_value_cutoff):
            continue
        terms.append(
            SimpleNamespace(
                source=ontology,
                termId=term_id,
                name=description,
                termSize=len(term_genes),
                intersectionSize=len(overlap),
                querySize=sample_size,
                geneRatio=len(overlap) / max(1, sample_size),
                hitPercent=(len(overlap) / max(1, len(term_genes))) * 100.0,
                pValue=float(p_value),
                adjPValue=adj_p_value,
                intersectingGenes=overlap,
            )
        )

    terms.sort(key=lambda term: (term.adjPValue, term.pValue, -term.intersectionSize))
    if counts is not None:
        counts.update(passingCutoff=len(terms), displayed=len(terms[:top_n]))
    return terms[:top_n]

def calculate_enrichment(database, query_genes, background_genes, *, min_term_size=20,
                         max_term_size=300, top_n=10, adj_p_value_cutoff=0.05):
    if min_term_size > max_term_size:
        raise ValueError("Minimum term size cannot be larger than maximum term size.")
    background, eligible = prepare_universe(database, background_genes, min_term_size, max_term_size)
    counts = {}
    terms = _enrichment_terms(query_genes, top_n, adj_p_value_cutoff, background, eligible, counts)
    return {"terms": [vars(term) for term in terms], "counts": counts,
            "annotatedBackground": sorted(background)}

def _explicit_gene_tokens(values):
    """Every member of an explicitly supplied gene list, once, sorted.

    One raw string is pasted text: split on `;`, `,` and whitespace. A list is
    already itemised: each item splits on `;` and `,` only, so an identifier
    that itself contains a space (the mouse GO table has three isoform ids
    such as "mERBB4/iso:JM-A CYT-2") survives when passed as one item.
    """
    if isinstance(values, str):
        return sorted({gene for token in _gene_tokens(values) for gene in token.split()})
    return sorted({gene for entry in values for gene in _gene_tokens(entry)})

def gene_list_terms_table(database, genes, background_genes=None, *, organism="Homo sapiens",
                         input_source="manual", named_list="", top_n=10, min_term_size=20,
                         max_term_size=300, adj_p_value_cutoff=0.05):
    genes = _explicit_gene_tokens(genes)
    background = None if background_genes is None else _explicit_gene_tokens(background_genes)
    if background is not None and (not background or set(genes).difference(background)):
        raise ValueError("The experiment background must include all query genes.")
    result = calculate_enrichment(database, genes, background, min_term_size=min_term_size,
        max_term_size=max_term_size, top_n=top_n, adj_p_value_cutoff=adj_p_value_cutoff)
    size = len(result["annotatedBackground"])
    context = dict(method="ORA", organism=organism, inputSource=input_source, namedList=named_list,
                   submittedGeneCount=len(genes), backgroundMode="global" if background is None else "experiment",
                   backgroundSize=size if background is None else len(background), annotatedBackgroundSize=size,
                   correctionMethod="Benjamini-Hochberg", testedTermCount=result["counts"]["searchSpace"],
                   **result["counts"], adjPValueCutoff=adj_p_value_cutoff, minTermSize=min_term_size,
                   maxTermSize=max_term_size, topN=top_n)
    return pd.DataFrame([{**context, **term, "intersectingGenes": ",".join(term["intersectingGenes"])}
                         for term in result["terms"]], columns=[*context, *['source', 'termId', 'name', 'termSize', 'intersectionSize', 'querySize', 'geneRatio', 'hitPercent', 'pValue', 'adjPValue', 'intersectingGenes']])

def ora_terms_table(result, request, direction):
    return pd.DataFrame(_ora_export_rows(result, request, direction))

def pathway_heatmap_table(data, metadata, database, **options):
    return _pathway_matrix(data, metadata, database, **options)[0]

def paired_sample_columns(
    metadata: pd.DataFrame,
    condition1: str,
    condition2: str,
) -> tuple[list[str], list[str]]:
    if str(condition1) == str(condition2):
        raise ValueError("Paired tests require two different conditions.")
    if "pair_id" not in metadata.columns:
        raise ValueError(
            "Paired tests require a 'pair_id' metadata column with one stable subject "
            "identifier per sample."
        )
    duplicate_samples = (
        metadata.loc[
            metadata["sample"].astype(str).duplicated(keep=False),
            "sample",
        ]
        .astype(str)
        .drop_duplicates()
        .tolist()
    )
    if duplicate_samples:
        raise ValueError(
            "Paired tests require each sample to appear once in metadata. "
            f"Duplicates: {', '.join(duplicate_samples)}."
        )

    def samples_by_id(condition: str) -> dict[str, str]:
        rows = metadata.loc[
            metadata["condition"].astype(str) == str(condition),
            ["sample", "pair_id"],
        ].copy()
        if rows.empty:
            raise ValueError(f"Condition '{condition}' does not have any annotated samples.")

        rows["sample"] = rows["sample"].astype(str)
        rows["pair_id"] = rows["pair_id"].where(rows["pair_id"].notna(), "").astype(str).str.strip()
        rows = rows.loc[rows["pair_id"] != ""]

        grouped: dict[str, list[str]] = {}
        for sample, pair_id in rows.itertuples(index=False, name=None):
            grouped.setdefault(pair_id, []).append(sample)

        duplicates = {key: values for key, values in grouped.items() if len(values) > 1}
        if duplicates:
            details = "; ".join(
                f"{key}: {', '.join(values)}" for key, values in sorted(duplicates.items())
            )
            raise ValueError(
                f"Paired tests require unique pair IDs within condition '{condition}'. "
                f"Duplicates: {details}."
            )
        return {key: values[0] for key, values in grouped.items()}

    left = samples_by_id(condition1)
    right = samples_by_id(condition2)
    pair_ids = [pair_id for pair_id in left if pair_id in right]
    if len(pair_ids) < 2:
        raise ValueError("Paired tests require at least two matched pair IDs.")
    return [left[key] for key in pair_ids], [right[key] for key in pair_ids]

def _volcano_groups(metadata, condition1, condition2, paired, condition1_control, condition2_control):
    if condition1 == condition2:
        raise ValueError("Please select two different conditions.")
    cols1 = metadata.loc[metadata["condition"] == condition1, "sample"].astype(str).tolist()
    cols2 = metadata.loc[metadata["condition"] == condition2, "sample"].astype(str).tolist()
    if not cols1 or not cols2:
        raise ValueError("Selected conditions do not have any annotated samples.")
    if paired:
        cols1, cols2 = paired_sample_columns(metadata, condition1, condition2)
    has_control1 = bool(condition1_control)
    has_control2 = bool(condition2_control)
    if has_control1 != has_control2:
        raise ValueError("Control-corrected volcano analysis requires both control conditions.")
    if has_control1 and has_control2:
        control_conditions = [
            str(condition1).strip(),
            str(condition1_control).strip(),
            str(condition2).strip(),
            str(condition2_control).strip(),
        ]
        if len(set(control_conditions)) != len(control_conditions):
            raise ValueError(
                "Control-corrected volcano analysis requires four distinct conditions; "
                "an experimental condition cannot be used as its own control."
            )
        ctrl1_cols = metadata.loc[metadata["condition"] == condition1_control, "sample"].astype(str).tolist()
        ctrl2_cols = metadata.loc[metadata["condition"] == condition2_control, "sample"].astype(str).tolist()
        if not ctrl1_cols or not ctrl2_cols:
            raise ValueError("Selected control conditions do not have any annotated samples.")
    else:
        ctrl1_cols = []
        ctrl2_cols = []

    count_groups = {condition1: cols1, condition2: cols2}
    if ctrl1_cols and ctrl2_cols:
        count_groups[str(condition1_control)] = ctrl1_cols
        count_groups[str(condition2_control)] = ctrl2_cols
    return count_groups

def _volcano_feature_frame(frame, label_column, groups):
    selected_columns = [label_column, *(c for cols in groups.values() for c in cols)]
    for extra in (
        "GeneNames",
        "Gene_group",
        "ProteinNames",
        "ProteinAccessions",
        "PTM_Collapse_key",
        "UPD_seq",
        "Protein_group",
        "Phosphoprotein",
        "site_num",
        "PTM_Collapse_keys",
    ):
        if extra in frame.columns and extra not in selected_columns:
            selected_columns.append(extra)

    return frame[[col for col in selected_columns if col in frame.columns]].copy()

def _volcano_eligibility(df, groups, condition1, condition2, paired, condition1_control, condition2_control):
    arr_x = df[groups[condition1]].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    arr_y = df[groups[condition2]].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)

    control_arrays: list[np.ndarray] = []
    if condition1_control and condition2_control:
        arr_ctrl1 = df[groups[condition1_control]].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
        arr_ctrl2 = df[groups[condition2_control]].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
        arr_x = arr_x - np.nanmean(arr_ctrl1, axis=1)[:, None]
        arr_y = arr_y - np.nanmean(arr_ctrl2, axis=1)[:, None]
        control_arrays = [arr_ctrl1, arr_ctrl2]

    n1 = np.sum(~np.isnan(arr_x), axis=1)
    n2 = np.sum(~np.isnan(arr_y), axis=1)
    valid_mask = (n1 >= 2) & (n2 >= 2)
    for control in control_arrays:
        # A control variance cannot be estimated from a single value, and it is
        # now part of the test statistic, so controls need replicates too.
        valid_mask &= np.sum(np.isfinite(control), axis=1) >= 2
    pair_counts = np.sum(np.isfinite(arr_x) & np.isfinite(arr_y), axis=1) if paired else None
    if pair_counts is not None:
        valid_mask &= pair_counts >= 2
    return arr_x, arr_y, control_arrays, n1, n2, valid_mask, pair_counts

def _workflow_label_candidates(kind: str) -> list[str]:
    if kind == "protein":
        return ["ProteinNames"]
    if kind == "phospho":
        return ["PTM_Collapse_key", "UPD_seq"]
    return ["Phosphoprotein", "ProteinNames", "PTM_Collapse_key"]

def _resolve_label_column(kind: str, identifier: str, frame: pd.DataFrame) -> str:
    candidates = _workflow_label_candidates(kind) if identifier == "workflow" else _gene_label_candidates(kind)
    resolved = _first_available_column(frame, candidates)
    if resolved:
        return resolved
    raise ValueError(
        "The selected identifier is not available for the current dataset: none of the columns "
        f"{', '.join(candidates)} is present. Name the identifier column accordingly in the file "
        "(for example rename a 'Protein' column to 'ProteinNames')."
    )

def _volcano_untested_rows(
    df: pd.DataFrame,
    groups: dict[str, list[str]],
    valid_mask: np.ndarray,
    pair_counts: np.ndarray | None = None,
) -> pd.DataFrame:
    """The rows the t-test cannot use, with their value counts and means per condition.

    A row needs at least two values in every compared condition. The values are
    the ones before any control correction, so the means are the condition's own.
    """
    samples = {column for columns in groups.values() for column in columns}
    identifiers = [column for column in df.columns
                   if column not in samples and not str(column).startswith(("n_imputed__", "n_measured__", "n_fully_imputed__", "n_partially_imputed__"))
                   and column != "imputed_values"]
    rows = df.loc[~np.asarray(valid_mask, dtype=bool)]
    out = rows[identifiers].reset_index(drop=True)
    short: list[list[str]] = [[] for _ in range(len(rows))]
    for condition, columns in groups.items():
        values = rows[columns].apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
        finite = np.isfinite(values)
        counts = finite.sum(axis=1)
        sums = np.where(finite, values, 0.0).sum(axis=1)
        out[f"n_{condition}"] = counts.astype(int)
        out[f"mean_{condition}"] = np.where(counts > 0, sums / np.maximum(counts, 1), np.nan)
        for index in np.flatnonzero(counts < 2):
            short[index].append(str(condition))
    reasons = ["fewer than 2 values in " + ", ".join(names) if names else "" for names in short]
    if pair_counts is not None:
        out["n_pairs"] = pair_counts[~np.asarray(valid_mask, dtype=bool)]
        reasons = ["; ".join(filter(None, [reason, "fewer than 2 complete pairs" if count < 2 else ""]))
                   for reason, count in zip(reasons, out["n_pairs"])]
    out["reason"] = reasons
    return out

def volcano_untested_table(data, metadata, condition1, condition2, *, kind="protein", identifier="workflow",
                          paired=False, condition1_control=None, condition2_control=None):
    groups = _volcano_groups(metadata, condition1, condition2, paired, condition1_control, condition2_control)
    df = _volcano_feature_frame(data, _resolve_label_column(kind, identifier, data), groups)
    *_, valid, pairs = _volcano_eligibility(df, groups, condition1, condition2, paired, condition1_control, condition2_control)
    return _volcano_untested_rows(df, groups, valid, pairs)

